    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos) | (6U << GPIO_AFRH_AFSEL9_Pos);

    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* 3. Configure TIM1 Time Base:
     *    TIM1 clock = 170 MHz.
     *    ARR = (170 MHz / 20 kHz) - 1 = 8500 - 1 = 8499.
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

    /* 4. Set Duty Cycles:
     *    CH1: 25 % of 8500 = 2125
     *    CH2: 75 % of 8500 = 6375
