#include "stm32g4xx.h"

int main(void)
{
    /* 1. Bật clock cho GPIOB và USART3 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    /* 2. Cấu hình chân PB10 (TX) và PB11 (RX) sang Alternate Function (AF7 - USART3) */
    // Đặt PB10 và PB11 ở Alternate Function mode (MODER = 10b)
    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (GPIO_MODER_MODE10_1 | GPIO_MODER_MODE11_1);

    // Cấu hình tốc độ cao (Very high speed) cho TX PB10
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED10_0 | GPIO_OSPEEDR_OSPEED10_1);

    // Bật pull-up cho chân RX PB11 (tránh nhiễu khi đường truyền idle)
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD11_Msk;
    GPIOB->PUPDR |= GPIO_PUPDR_PUPD11_0;

    // Gán AF7 (0111b) cho PB10 và PB11 trong AFRH (AFR[1])
    GPIOB->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL10_Pos) | (0xFU << GPIO_AFRH_AFSEL11_Pos));
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);

    /* 3. Cấu hình USART3: 921600 baud, 8N1, Oversampling by 16 */
    // Mặc định USART3SEL trong RCC->CCIPR = 00b (PCLK1 = 170 MHz)
    // Với oversampling by 16 (OVER8 = 0): USARTDIV = fCK / Baud = 170000000 / 921600 ≈ 184.4618
    // Làm tròn BRR = 184 = 0x00B8 -> Sai số thực tế: ~ +0.25% (đạt yêu cầu < ±2%)
    USART3->BRR = 184U;

    // Cấu hình 8 bit data (M1:M0 = 00), 1 stop bit (STOP = 00 trong CR2), oversampling by 16 (OVER8 = 0)
    // Bật Transmitter (TE), Receiver (RE) và kích hoạt USART (UE)
    USART3->CR1 = USART_CR1_TE | USART_CR1_RE;
    USART3->CR1 |= USART_CR1_UE;

    while (1)
    {
        // Vòng lặp chính
    }
}
```

### Giải thích ngắn gọn:
1. **Clock & GPIO**:
   - Clock GPIOB nằm trên AHB2 (`RCC_AHB2ENR_GPIOBEN`), USART3 nằm trên APB1 (`RCC_APB1ENR1_USART3EN`).
   - PB10 và PB11 được chuyển sang chế độ Alternate Function AF7 (USART3_TX và USART3_RX) [DS12288 p.76].
2. **Tính toán Baud Rate**:
   - Nguồn clock mặc định của USART3 là PCLK1 = 170 MHz.
   - Khi oversampling by 16 (`USART_CR1_OVER8 = 0`), giá trị ghi vào `USART3->BRR` chính là `USARTDIV = round(170,000,000 / 921,600) = 184`.
   - Baud rate thực tế: $\frac{170,000,000}{184} \approx 923,913\text{ baud}$ (sai số xấp xỉ $+0.25\%$, thỏa mãn giới hạn $\pm 2\%$) [RM0440 p.1176].
3. **Cấu hình thanh ghi điều khiển**:
   - `USART3->BRR` được thiết lập trước khi bật bit `UE`.
   - Các giá trị reset của `USART3->CR1` và `USART3->CR2` mặc định tương ứng với 8 data bit, không parity (`PCE = 0`), và 1 stop bit (`STOP[1:0] = 00b`). Bật `TE`, `RE` và `UE` trong `USART3->CR1` để hoàn tất cấu hình.

