    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (GPIO_MODER_MODE10_1 | GPIO_MODER_MODE11_1);

    // Cấu hình tốc độ cao (Very high speed) cho TX PB10
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED10_0 | GPIO_OSPEEDR_OSPEED10_1);

    // Bật pull-up cho chân RX PB11 (tránh nhiễu khi đường truyền idle)
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD11_Msk;
    GPIOB->PUPDR |= GPIO_PUPDR_PUPD11_0;

    // Gán AF7 (0111b) cho PB10 và PB11 trong AFRH (AFR[1])
    GPIOB->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL10_Pos) | (0xFU << GPIO_AFRH_AFSEL11_Pos));
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);

    /* 3. Cấu hình USART3: 921600 baud, 8N1, Oversampling by 16 */
    // Mặc định USART3SEL trong RCC->CCIPR = 00b (PCLK1 = 170 MHz)
    // Với oversampling by 16 (OVER8 = 0): USARTDIV = fCK / Baud = 170000000 / 921600 ≈ 184.4618
    // Làm tròn BRR = 184 = 0x00B8 -> Sai số thực tế: ~ +0.25% (đạt yêu cầu < ±2%)
    USART3->BRR = 184U;

    // Cấu hình 8 bit data (M1:M0 = 00), 1 stop bit (STOP = 00 trong CR2), oversampling by 16 (OVER8 = 0)
    // Bật Transmitter (TE), Receiver (RE) và kích hoạt USART (UE)
    USART3->CR1 = USART_CR1_TE | USART_CR1_RE;
    USART3->CR1 |= USART_CR1_UE;

    while (1)
    {
        // Vòng lặp chính
    }
