     * f_CK = 170 000 000 Hz, Oversampling by 16 (OVER8 = 0)
     * BRR = round(f_CK / Baud) = round(170000000 / 921600) = 184
     * Tốc độ thực tế: 170000000 / 184 = 923913.04 baud (sai số ~ +0.25%, < 2%)
     */
    USART3->BRR = 184U;

