    GPIOB->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOB->MODER |= (2UL << GPIO_MODER_MODE8_Pos) | (2UL << GPIO_MODER_MODE9_Pos);

    /* Open-drain output type (OTYPER = 1) */
    GPIOB->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* High speed (OSPEEDR = 11b) */
    GPIOB->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED8_Pos) | (3UL << GPIO_OSPEEDR_OSPEED9_Pos);

