    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);
    GPIOB->PUPDR |= (1UL << GPIO_PUPDR_PUPD8_Pos) | (1UL << GPIO_PUPDR_PUPD9_Pos);

