    GPIOB->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk);
    GPIOB->AFR[1] |= (4UL << GPIO_AFRH_AFSEL8_Pos) | (4UL << GPIO_AFRH_AFSEL9_Pos);

    /* 3. Configure I2C1 timing while disabled (PE = 0) */
    I2C1->CR1 &= ~I2C_CR1_PE;

