     * - PRESC = 3  => tPRESC = (3 + 1) * 62.5 ns = 250 ns
     * - tSYNC1 = tSYNC2 = 2 * tI2CCLK = 125 ns (total sync = 250 ns)
     * - SCLL  = 19 => tSCLL = (19 + 1) * 250 ns = 5000 ns -> tLOW  = 5000 + 125 = 5125 ns (>= 4700 ns)
     * - SCLH  = 18 => tSCLH = (18 + 1) * 250 ns = 4750 ns -> tHIGH = 4750 + 125 = 4875 ns (>= 4000 ns)
     * - tSCL  = tLOW + tHIGH = 10000 ns => fSCL = 100 kHz
     * - SDADEL = 2 (500 ns data hold delay), SCLDEL = 4 (1250 ns data setup delay)
     */
    I2C1->TIMINGR = (3UL  << I2C_TIMINGR_PRESC_Pos)  |
