    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Chuyển sang Range 1 Boost mode để chạy được tần số lên đến 170 MHz [RM0440 p.184] */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

