    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    /* 4. Đảm bảo HSI16 đã sẵn sàng */
    while ((RCC->CR & RCC_CR_HSIRDY) == 0);

    /* 5. Tắt PLL trước khi cấu hình */
    RCC->CR &= ~RCC_CR_PLLON;
    while (RCC->CR & RCC_CR_PLLRDY);

    /* 6. Cấu hình PLL:
     *    f_VCO = (f_PLLIN / M) * N = (16 MHz / 4) * 85 = 340 MHz
     *    f_PLLCLK = f_VCO / R = 340 MHz / 2 = 170 MHz
     *    - PLLSRC: HSI16
     *    - PLLM: /4 (giá trị ghi vào bitfield là M - 1 = 3)
     *    - PLLN: *85
     *    - PLLR: /2 (giá trị 00b tương ứng chia 2)
     *    - Bật ngõ ra PLLR (PLLREN)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI
                 | (3U << RCC_PLLCFGR_PLLM_Pos)
                 | (85U << RCC_PLLCFGR_PLLN_Pos)
                 | (0U << RCC_PLLCFGR_PLLR_Pos)
                 | RCC_PLLCFGR_PLLREN;

    /* 7. Bật PLL và đợi PLL khóa (PLLRDY) */
    RCC->CR |= RCC_CR_PLLON;
    while ((RCC->CR & RCC_CR_PLLRDY) == 0);

    /* 8. Chuyển SYSCLK sang nguồn PLL và đợi xác nhận từ SWS */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
