Dưới đây là mã nguồn C bare-metal hoàn chỉnh điều khiển vi điều khiển STM32G474 theo chuẩn CMSIS để tạo tín hiệu PWM 20 kHz với chu kỳ nhiệm vụ (duty cycle) 25 % trên chân PA8 (TIM1_CH1).

### Mã nguồn C (`main.c`)

```c
#include "stm32g4xx.h"

int main(void)
{
    /* 1. Kích hoạt xung nhịp cho ngoại vi GPIOA qua thanh ghi RCC_AHB2ENR */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;

    /* 2. Cấu hình chân PA8 sử dụng chức năng Alternate Function 6 (AF6: TIM1_CH1) */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFU << GPIO_AFRH_AFSEL8_Pos)) | (6U << GPIO_AFRH_AFSEL8_Pos);

    /* Cấu hình PA8 ở chế độ Alternate Function (MODER8 = 10b) */
    GPIOA->MODER = (GPIOA->MODER & ~(3U << GPIO_MODER_MODE8_Pos)) | (2U << GPIO_MODER_MODE8_Pos);

    /* 3. Kích hoạt xung nhịp cho bộ định thời nâng cao TIM1 qua thanh ghi RCC_APB2ENR */
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 4. Cấu hình tần số và chu kỳ nhiệm vụ (Duty Cycle):
     * TIM1 được cấp xung từ APB2 domain. Khi hệ số chia APB2 prescaler != 1 (ở đây APB2 DIV = 2),
     * tần số xung nhịp tim_ker_ck của TIM1 được nhân đôi: 
     * f_TIM1CLK = 2 * PCLK2 = 2 * 85 MHz = 170 MHz [STM32G474_RM0440 p.281].
     *
     * Công thức tần số PWM chế độ edge-aligned:
     * f_PWM = f_TIM1CLK / ((PSC + 1) * (ARR + 1))
     * Với f_PWM = 20 kHz:
     * (PSC + 1) * (ARR + 1) = 170000000 / 20000 = 8500
     * Chọn PSC = 0 => ARR = 8499 (sai số tần số 0 %).
     *
     * Chu kỳ nhiệm vụ (Duty Cycle) = 25 % trong PWM mode 1 (active-high):
     * Duty = CCR1 / (ARR + 1) = CCR1 / 8500 = 0.25 => CCR1 = 2125 (sai số duty 0 %).
     */
    TIM1->PSC = 0U;
    TIM1->ARR = 8499U;
    TIM1->CCR1 = 2125U;

    /* 5. Cấu hình kênh 1 ở chế độ PWM mode 1 (OC1M = 0110b) và bật preload (OC1PE = 1) */
    TIM1->CCMR1 = (TIM1->CCMR1 & ~(TIM_CCMR1_CC1S | TIM_CCMR1_OC1M)) |
                  TIM_CCMR1_OC1PE |
                  (6U << TIM_CCMR1_OC1M_Pos);

    /* 6. Cho phép xuất tín hiệu ở Channel 1 (CC1E = 1 trong TIM1_CCER, phân cực active-high mặc định khi CC1P = 0) */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 7. Kích hoạt đầu ra chính (Main Output Enable - MOE = 1 trong TIM1_BDTR) cho timer nâng cao TIM1 */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 8. Kích hoạt bộ đệm tự nạp lại (ARPE = 1) và khởi động bộ đếm (CEN = 1 trong TIM1_CR1) */
    TIM1->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    while (1)
    {
        /* Vòng lặp chính */
    }
}
```

