#include "stm32g4xx.h"

int main(void)
{
    /* 1. Bật xung nhịp cho GPIOA trên bus AHB2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;

    /* 2. Cấu hình chân PA8 sang chế độ Alternate Function (AF6 = TIM1_CH1) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE8_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos); /* AF mode (10b) */

    GPIOA->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk);
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos); /* AF6 */

    /* 3. Bật xung nhịp cho TIM1 trên bus APB2 */
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 4. Cấu hình chu kỳ và độ rộng xung cho 20 kHz, duty cycle 25%
     * TIM1CLK = 170 MHz (do APB2 prescaler = 2 => TIMxCLK = 2 * PCLK2 = 170 MHz)
     * f_PWM = 170 MHz / ((0 + 1) * (8499 + 1)) = 20000 Hz
     * Duty = 2125 / (8499 + 1) = 25%
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    /* 5. Cấu hình kênh 1 ở PWM Mode 1 (OC1M = 0110b) và bật preload (OC1PE) */
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 6. Bật ngõ ra Channel 1 (CC1E = 1, cực tính mặc định là active-high CC1P = 0) */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 7. Kích hoạt Main Output Enable (MOE) - bắt buộc đối với Advanced Timer như TIM1 */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 8. Bắt đầu đếm (Counter Enable) */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* Vòng lặp vô hạn */
    while (1)
    {
    }
}
