    GPIOC->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOC->AFR[0] |= (4U << GPIO_AFRL_AFSEL6_Pos);

    /* 3. Configure TIM8 Time Base:
     * APB2 prescaler is 2, so the timer kernel clock is multiplied by 2:
     * TIM8CLK = PCLK2 * 2 = 85 MHz * 2 = 170 MHz.
     * Target frequency = 10 kHz:
