     *    f_tim = 170 MHz (do APB2 prescaler = 1 nên TIM16CLK = PCLK2 = 170 MHz).
     *    f_PWM = f_tim / ((PSC + 1) * (ARR + 1))
     *    170,000,000 / ((1 + 1) * (42499 + 1)) = 170,000,000 / (2 * 42500) = 2,000 Hz
     */
    TIM16->PSC = 1;
    TIM16->ARR = 42499;

    /* 6. Cấu hình giá trị so sánh kênh 1 (CCR1) cho duty cycle 75 %:
     *    Duty = CCR1 / (ARR + 1) = 31875 / 42500 = 75.0 %
     */
    TIM16->CCR1 = 31875;

    /* 7. Cấu hình chế độ PWM mode 1 (OC1M = 0110b) và bật tính năng preload (OC1PE = 1) */
    TIM16->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM16->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 8. Kích hoạt đầu ra kênh 1 (CC1E = 1, cực tính mặc định là active-high với CC1P = 0) */
    TIM16->CCER |= TIM_CCER_CC1E;

