    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 and PA9 as alternate function AF6 (TIM1_CH1, TIM1_CH2) */
    /* PA8 is AFR[1] bits [3:0], PA9 is AFR[1] bits [7:4] */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0x000000FFU)) | (6U << 0) | (6U << 4);

    /* Set mode to Alternate Function (MODER = 10b) for PA8 and PA9 */
    GPIOA->MODER = (GPIOA->MODER & ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk))
                 | (2U << GPIO_MODER_MODE8_Pos)
                 | (2U << GPIO_MODER_MODE9_Pos);

    /* 3. Configure TIM1 timebase for 20 kHz PWM */
    /* Timer clock = 170 MHz. Target freq = 20 kHz -> (PSC + 1)*(ARR + 1) = 8500 */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

    /* 4. Set duty cycles: 25% on CH1, 75% on CH2 */
    TIM1->CCR1 = 2125;
    TIM1->CCR2 = 6375;

    /* 5. Configure PWM mode 1 and enable preload for channels 1 & 2 in CCMR1 */
    TIM1->CCMR1 = (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE
