    GPIOB->AFR[1] &= ~((0xFUL << GPIO_AFRH_AFSEL10_Pos) | (0xFUL << GPIO_AFRH_AFSEL11_Pos));
    GPIOB->AFR[1] |= ((7UL << GPIO_AFRH_AFSEL10_Pos) | (7UL << GPIO_AFRH_AFSEL11_Pos));

