    /* 1. Bật clock cho GPIOB (AHB2) và USART3 (APB1) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    /* 2. Cấu hình Alternate Function AF7 (USART3_TX, USART3_RX) cho PB10 và PB11 */
    GPIOB->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL10_Pos) | (0xFU << GPIO_AFRH_AFSEL11_Pos));
    GPIOB->AFR[1] |= ((7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos));

    /* 3. Cấu hình chế độ Alternate Function (MODER = 10b) cho PB10 và PB11 */
    GPIOB->MODER &= ~((3U << GPIO_MODER_MODE10_Pos) | (3U << GPIO_MODER_MODE11_Pos));
    GPIOB->MODER |= ((2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos));

    /* 4. Đảm bảo USART3 đang tắt (UE = 0) trước khi cấu hình */
    USART3->CR1 &= ~USART_CR1_UE;

    /* 5. Cấu hình khung truyền: 8 data bits (M[1:0] = 00), no parity (PCE = 0), oversampling by 16 (OVER8 = 0) */
    USART3->CR1 &= ~(USART_CR1_M1 | USART_CR1_M0 | USART_CR1_PCE | USART_CR1_OVER8);

    /* 6. Cấu hình 1 stop bit (STOP[1:0] = 00) */
    USART3->CR2 &= ~USART_CR2_STOP;

