     * Clock USART3 mặc định lấy từ PCLK1 = 170 MHz (RCC_CCIPR USART3SEL = 00b [STM32G474_RM0440 p.322]).
     * Với OVER8 = 0: BRR = USARTDIV = round(170 000 000 / 921 600) = round(184.457) = 184 [STM32G474_RM0440 p.1707-1708].
     */
    USART3->BRR = 184U;

    /* 8. Bật bộ phát (TE) và bộ thu (RE) */
    USART3->CR1 |= (USART_CR1_TE | USART_CR1_RE);

    /* 9. Bật USART3 (UE = 1) */
    USART3->CR1 |= USART_CR1_UE;

    /* Vòng lặp chính */
    while (1) {
    }
