#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable peripheral clocks for GPIOB and I2C1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C1EN;

    /* 2. Configure PB8 (I2C1_SCL) and PB9 (I2C1_SDA) as AF4, open-drain */
    /* Set MODER to Alternate Function mode (0b10) for PB8 and PB9 */
    GPIOB->MODER = (GPIOB->MODER & ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk))
                 | (2UL << GPIO_MODER_MODE8_Pos)
                 | (2UL << GPIO_MODER_MODE9_Pos);

    /* Set Output Type to Open-Drain for PB8 and PB9 */
    GPIOB->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* Set Alternate Function AF4 for PB8 and PB9 in AFR[1] (AFRH) */
    GPIOB->AFR[1] = (GPIOB->AFR[1] & ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk))
                  | (4UL << GPIO_AFRH_AFSEL8_Pos)
                  | (4UL << GPIO_AFRH_AFSEL9_Pos);

    /* Enable internal pull-up resistors for PB8 and PB9 */
    GPIOB->PUPDR = (GPIOB->PUPDR & ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk))
                 | (1UL << GPIO_PUPDR_PUPD8_Pos)
                 | (1UL << GPIO_PUPDR_PUPD9_Pos);

    /* 3. Configure I2C1 timing while peripheral is disabled (PE = 0) */
    I2C1->CR1 &= ~I2C_CR1_PE;

    /*
