#include "stm32g4xx.h"

int main(void) {
    /* 1. Select HSI16 (16 MHz) as the I2C1 kernel clock in RCC_CCIPR (I2C1SEL[1:0] = 10b) */
    RCC->CCIPR = (RCC->CCIPR & ~RCC_CCIPR_I2C1SEL_Msk) | (2U << RCC_CCIPR_I2C1SEL_Pos);

    /* 2. Enable peripheral clocks for GPIOB (AHB2) and I2C1 (APB1ENR1) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C1EN;

    /* 3. Configure PB8 (I2C1_SCL) and PB9 (I2C1_SDA) */
    /* Map PB8 and PB9 to Alternate Function 4 (AF4) in AFRH */
    GPIOB->AFR[1] = (GPIOB->AFR[1] & ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk))
                  | (4U << GPIO_AFRH_AFSEL8_Pos)
                  | (4U << GPIO_AFRH_AFSEL9_Pos);

    /* Configure PB8 and PB9 as Open-Drain */
    GPIOB->OTYPER |= GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9;

    /* Enable pull-up resistors on PB8 and PB9 */
    GPIOB->PUPDR = (GPIOB->PUPDR & ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk))
                 | (1U << GPIO_PUPDR_PUPD8_Pos)
                 | (1U << GPIO_PUPDR_PUPD9_Pos);

    /* Set mode to Alternate Function (10b) for PB8 and PB9 */
    GPIOB->MODER = (GPIOB->MODER & ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk))
                 | (2U << GPIO_MODER_MODE8_Pos)
                 | (2U << GPIO_MODER_MODE9_Pos);

    /* 4. Configure I2C1 timing for 400 kHz Fast-mode with 16 MHz HSI16 kernel clock */
    /* Ensure peripheral is disabled (PE = 0) before modifying TIMINGR */
    I2C1->CR1 &= ~I2C_CR1_PE;

    /*
     * TIMINGR configuration (from RM0440 Table 360, 400 kHz @ 16 MHz):
