#include "stm32g4xx.h"

int main(void)
{
    /* 1. Đảm bảo dao động nội HSI16 đã được bật và ổn định */
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY))
    {
    }

    /* 2. Bật xung nhịp cho khối PWR (Power Interface) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    (void)RCC->APB1ENR1; /* Đọc trễ để đảm bảo clock ngoại vi đã bật */

