     * Để hoạt động ở tần số > 150 MHz (lên đến 170 MHz), bit R1MODE trong PWR_CR5
     * phải được xóa về 0 (0 = Main regulator in Range 1 boost mode).
     */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 4. Cấu hình độ trễ Flash (Flash Latency):
     * Trong Range 1 Boost mode, tần số HCLK = 170 MHz đòi hỏi 4 chu kỳ chờ (LATENCY = 4 WS).
     * Ghi giá trị vào FLASH_ACR và chờ xác nhận.
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY_Msk) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_4WS)
    {
    }

    /* 5. Cấu hình Main PLL từ HSI16:
     * Nguồn vào PLL: HSI16 = 16 MHz (PLLSRC = 10b).
     * Hệ số chia PLLM: M = 4 (ghi giá trị 3 vào PLLM[3:0]) => f_VCO_IN = 16 MHz / 4 = 4 MHz.
     * Hệ số nhân PLLN: N = 85 (ghi 85 vào PLLN[6:0]) => f_VCO = 4 MHz * 85 = 340 MHz.
     * Hệ số chia PLLR: R = 2 (ghi 00b vào PLLR[1:0]) => f_PLL_R = 340 MHz / 2 = 170 MHz.
     * Bật ngõ ra PLL_R bằng bit PLLREN.
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

