{
    /* 1. Kích hoạt clock cho ngoại vi PWR qua thanh ghi RCC_APB1ENR1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Cấu hình Range 1 Boost Mode: xóa bit R1MODE trong PWR_CR5 để cho phép SYSCLK lên đến 170 MHz */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Cấu hình số Flash Wait States: 4 WS (LATENCY = 4) cho HCLK = 170 MHz ở Range 1 boost mode */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY_Msk) | FLASH_ACR_LATENCY_4WS;
