     *    - Nguồn cấp PLL: HSI16 (PLLSRC = 0b10)
     *    - PLLM = 4: nạp giá trị (4 - 1) = 3 vào trường PLLM (bits [7:4])
     *    - PLLN = 85: nạp giá trị 85 vào trường PLLN (bits [14:8])
     *    - PLLR = 2: nạp giá trị 0b00 vào trường PLLR (bits [26:25])
     *    - Bật ngõ ra PLLCLK (PLL "R"): bật bit PLLREN (bit 24)
     */
    RCC->PLLCFGR = (2U << RCC_PLLCFGR_PLLSRC_Pos) |
                   (3U << RCC_PLLCFGR_PLLM_Pos)   |
                   (85U << RCC_PLLCFGR_PLLN_Pos)  |
                   (0U << RCC_PLLCFGR_PLLR_Pos)   |
                   RCC_PLLCFGR_PLLREN;

