    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW_Msk) | RCC_CFGR_SW_PLL;

    /* 10. Chờ phần cứng chuyển đổi xong (kiểm tra trường SWS báo PLL đang làm SYSCLK) */
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL)
    {
    }

    /* Vòng lặp vô tận sau khi hoàn tất thiết lập clock */
    while (1)
    {
    }
