Dưới đây là mã nguồn C bare-metal cấu hình cây xung nhịp (clock tree) cho STM32G474 từ trạng thái reset ban đầu lên tần số SYSCLK = HCLK = PCLK1 = PCLK2 = 170 MHz sử dụng nguồn HSI16 (16 MHz) qua bộ nhân PLL, đáp ứng chuẩn CMSIS và không sử dụng thư viện HAL/LL.

### Mã nguồn C

```c
#include "stm32g4xx.h"

int main(void)
{
    /* 1. Bật clock cho Power Controller (PWR) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Kích hoạt Range 1 boost mode bằng cách xóa bit R1MODE trong PWR_CR5
     * (Cần thiết khi SYSCLK > 150 MHz để đạt mức tối đa 170 MHz) */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Cấu hình độ trễ Flash (Flash latency) thành 4 wait states (4WS)
     * Đối với Range 1 boost mode và HCLK lên tới 170 MHz */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Chờ giá trị latency được áp dụng */
    }

    /* 4. Đảm bảo dao động nội HSI16 đã được bật và sẵn sàng */
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY)) {
        /* Chờ HSI16 sẵn sàng */
    }

    /* 5. Cấu hình PLL:
     * - PLLSRC: HSI16 (16 MHz)
     * - PLLM = 4 (giá trị nạp vào trường PLLM là 3, vì phép chia = PLLM + 1):
     *     fVCO_IN = 16 MHz / 4 = 4 MHz (nằm trong dải cho phép 2.66 - 16 MHz)
     * - PLLN = 85:
     *     fVCO = 4 MHz * 85 = 340 MHz (nằm trong dải cho phép 96 - 344 MHz)
     * - PLLR = 2 (mã nạp 0b00 ứng với /2):
     *     fPLL_R = 340 MHz / 2 = 170 MHz
     * - Bật ngõ ra PLL_R: PLLREN
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* 6. Bật PLL và chờ cờ PLLRDY */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Chờ PLL khóa pha ổn định */
    }

    /* 7. Trạng thái chuyển tiếp theo khuyến nghị của manual khi chuyển sang HCLK > 80 MHz:
     * Tạm thời đặt bộ chia AHB (HPRE) = /2 trước khi chuyển nguồn SYSCLK sang PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;

    /* 8. Chuyển nguồn SYSCLK sang PLL (SW = 0b11) và chờ cờ trạng thái SWS */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Chờ hệ thống chuyển sang dùng PLL làm SYSCLK */
    }

    /* 9. Trì hoãn ít nhất 1 us trong trạng thái chuyển tiếp */
    for (volatile uint32_t i = 0; i < 50; i++) {
        __NOP();
    }

    /* 10. Đặt lại bộ chia AHB về /1:
     * SYSCLK = 170 MHz -> HCLK = 170 MHz.
     * Các bộ chia APB1 (PPRE1) và APB2 (PPRE2) mặc định khi reset là /1,
     * do đó PCLK1 = PCLK2 = 170 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;

    /* Vòng lặp vô hạn kết thúc quá trình cấu hình */
    while (1) {
    }
}
